param(
    [Parameter(Mandatory = $true, Position = 0)]
    [ValidateNotNullOrEmpty()]
    [string]$ProjectPath
)

$ErrorActionPreference = 'Stop'

$Package = Split-Path -Parent $MyInvocation.MyCommand.Path
$Overlay = Join-Path $Package 'overlay'

function Test-PlotboxRoot {
    param([string]$Path)

    $RequiredRelativePaths = @(
        'packages/plotter_core/plotter_core/models.py'
        'packages/plotter_core/plotter_core/maps/osm.py'
        'apps/web/src/maps/MapControls.tsx'
        'services/api/plotterapp_api/main.py'
    )

    foreach ($RelativePath in $RequiredRelativePaths) {
        if (-not (Test-Path -LiteralPath (Join-Path $Path $RelativePath))) {
            return $false
        }
    }

    return $true
}

try {
    $Root = (Resolve-Path -LiteralPath $ProjectPath -ErrorAction Stop).Path
} catch {
    throw "ProjectPath does not exist: $ProjectPath"
}

if (-not (Test-PlotboxRoot -Path $Root)) {
    throw "ProjectPath is not the Plotbox repository root: $Root"
}

Write-Host "using Plotbox repository $Root"

function Decode-Text {
    param([string]$Base64)
    return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Base64))
}

function Replace-Once {
    param([string]$Path, [string]$Old, [string]$New)

    $Text = [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
    $UsesCrLf = $Text.Contains("`r`n")

    # Match using LF so Windows Git checkouts with core.autocrlf/CRLF do not break patches.
    $NormalizedText = $Text.Replace("`r`n", "`n")
    $NormalizedOld = $Old.Replace("`r`n", "`n")
    $NormalizedNew = $New.Replace("`r`n", "`n")

    $Index = $NormalizedText.IndexOf($NormalizedOld, [System.StringComparison]::Ordinal)
    if ($Index -lt 0) {
        throw "Expected source block was not found in $Path. The repository file differs from the version this bundle was built against."
    }

    $Updated =
        $NormalizedText.Substring(0, $Index) +
        $NormalizedNew +
        $NormalizedText.Substring($Index + $NormalizedOld.Length)

    if ($UsesCrLf) {
        $Updated = $Updated.Replace("`n", "`r`n")
    }

    [System.IO.File]::WriteAllText($Path, $Updated, (New-Object System.Text.UTF8Encoding($false)))
}

function Append-Once {
    param([string]$Path, [string]$Marker, [string]$Content)
    $Text = [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
    if ($Text.Contains($Marker)) { return }
    $Updated = $Text.TrimEnd() + "`n`n" + $Content.TrimEnd() + "`n"
    [System.IO.File]::WriteAllText($Path, $Updated, (New-Object System.Text.UTF8Encoding($false)))
}

function Copy-Overlay {
    Get-ChildItem -Path $Overlay -File -Recurse | ForEach-Object {
        $Relative = [System.IO.Path]::GetRelativePath($Overlay, $_.FullName)
        $Target = Join-Path $Root $Relative
        $TargetDirectory = Split-Path -Parent $Target
        if (-not (Test-Path $TargetDirectory)) { New-Item -ItemType Directory -Path $TargetDirectory -Force | Out-Null }
        Copy-Item -LiteralPath $_.FullName -Destination $Target -Force
        Write-Host "replaced $Relative"
    }
}

function Apply-Patches {
    $Path = Join-Path $Root 'packages/plotter_core/plotter_core/models.py'
    $Old = Decode-Text ''
    $New = Decode-Text ''
    Replace-Once -Path $Path -Old $Old -New $New

    $Path = Join-Path $Root 'packages/plotter_core/plotter_core/models.py'
    $Old = Decode-Text ''
    $New = Decode-Text ''
    Replace-Once -Path $Path -Old $Old -New $New

    $Path = Join-Path $Root 'apps/web/src/types.ts'
    $Old = Decode-Text ''
    $New = Decode-Text ''
    Replace-Once -Path $Path -Old $Old -New $New

    $Path = Join-Path $Root 'services/api/plotterapp_api/main.py'
    $Old = Decode-Text ''
    $New = Decode-Text ''
    Replace-Once -Path $Path -Old $Old -New $New

    $Path = Join-Path $Root 'services/api/plotterapp_api/main.py'
    $Old = Decode-Text 'ICAgICAgICB2ZXJzaW9uPSIwLjMuMCIsCg=='
    $New = Decode-Text 'ICAgICAgICB2ZXJzaW9uPSIwLjQuMSIsCg=='
    Replace-Once -Path $Path -Old $Old -New $New

    $Path = Join-Path $Root 'services/api/plotterapp_api/main.py'
    $Old = Decode-Text ''
    $New = Decode-Text ''
    Replace-Once -Path $Path -Old $Old -New $New

    $Path = Join-Path $Root 'packages/plotter_core/plotter_core/maps/__init__.py'
    $Marker = Decode-Text 'IyB0ZXJyYWluIGV4cG9ydHMgdjAuNC4x'
    $Content = Decode-Text ''
    Append-Once -Path $Path -Marker $Marker -Content $Content

    $Path = Join-Path $Root 'apps/web/package.json'
    $Old = Decode-Text 'ICAidmVyc2lvbiI6ICIwLjMuNSIsCg=='
    $New = Decode-Text 'ICAidmVyc2lvbiI6ICIwLjQuMSIsCg=='
    Replace-Once -Path $Path -Old $Old -New $New

    $Path = Join-Path $Root 'config.yaml'
    $Old = Decode-Text 'dmVyc2lvbjogIjAuMy41Igo='
    $New = Decode-Text 'dmVyc2lvbjogIjAuNC4xIgo='
    Replace-Once -Path $Path -Old $Old -New $New

    $Path = Join-Path $Root 'apps/web/src/index.css'
    $Marker = Decode-Text 'TWFwIGNvbnRyb2xzIC0gdmVyc2lvbiAwLjQuMQ=='
    $Content = Decode-Text ''
    Append-Once -Path $Path -Marker $Marker -Content $Content

    $Path = Join-Path $Root 'README.md'
    $Marker = Decode-Text 'IyMgRXh0ZW5kZWQgcGVuLXBsb3QgbWFwIGxheWVycyAoMC40LjEp'
    $Content = Decode-Text ''
    Append-Once -Path $Path -Marker $Marker -Content $Content

}

function Run-OptionalTools {
    if (Get-Command uv -ErrorAction SilentlyContinue) {
        & uv run python scripts/export_schemas.py
        if ($LASTEXITCODE -ne 0) { throw 'Schema regeneration failed' }
        Write-Host 'regenerated packages/schemas'
    } else {
        Write-Host "uv not found - run 'uv run python scripts/export_schemas.py' before committing"
    }

    if (Get-Command pnpm -ErrorAction SilentlyContinue) {
        Push-Location (Join-Path $Root 'apps/web')
        try {
            & pnpm exec prettier --write src/maps/MapControls.tsx src/types.ts src/index.css
            if ($LASTEXITCODE -ne 0) { throw 'Frontend formatting failed' }
            Write-Host 'formatted changed frontend files'
        } finally {
            Pop-Location
        }
    } else {
        Write-Host 'pnpm not found - run frontend formatting before committing'
    }
}

Apply-Patches
Copy-Overlay
Run-OptionalTools
Write-Host 'Plotbox map expansion v0.4.4 applied.'
